/**
 * Disaster Response Platform — Worker Entry Point
 * T1: Platform skeleton booting Hono app with /healthz
 * T2: Bindings wired via wrangler.jsonc, types via `wrangler types`
 *    + DO class stubs exported so wrangler dev boots
 *
 * Full Hono app skeleton (T4) replaces this with route groups, middleware, chanfana.
 * Full DO implementations land in their respective phase todos.
 */
import { Hono } from 'hono';

// Cloudflare Worker bindings (generated by `wrangler types`)
export interface Env {
  // D1
  db: D1Database;
  // R2
  media: R2Bucket;
  exports: R2Bucket;
  // Queues (producers)
  ingestQ: Queue<unknown>;
  alertQ: Queue<unknown>;
  aiQ: Queue<unknown>;
  droneQ: Queue<unknown>;
  geocodeQ: Queue<unknown>;
  webhookIngestQ: Queue<unknown>;
  webhookDeliveryQ: Queue<unknown>;
  // Durable Objects
  IncidentRoom: DurableObjectNamespace;
  RateLimiter: DurableObjectNamespace;
  TaskTimer: DurableObjectNamespace;
  ShelterCounter: DurableObjectNamespace;
  AmbulanceQueue: DurableObjectNamespace;
  AgencyRoom: DurableObjectNamespace;
  // KV
  cache: KVNamespace;
  locales: KVNamespace;
  // Vectorize
  embeddings: VectorizeIndex;
  // Analytics Engine
  metrics: AnalyticsEngineDataset;
  // Workers AI
  ai: Ai;
  // Vars
  ENVIRONMENT: string;
}

const app = new Hono<{ Bindings: Env }>();

/**
 * GET /healthz — lightweight liveness check.
 * Returns ok=true + list of all bindings for verification (T2 acceptance).
 */
app.get('/healthz', (c) => {
  return c.json({
    ok: true,
    bindings: {
      db: !!c.env.db,
      media: !!c.env.media,
      exports: !!c.env.exports,
      ingestQ: !!c.env.ingestQ,
      alertQ: !!c.env.alertQ,
      aiQ: !!c.env.aiQ,
      droneQ: !!c.env.droneQ,
      geocodeQ: !!c.env.geocodeQ,
      webhookIngestQ: !!c.env.webhookIngestQ,
      webhookDeliveryQ: !!c.env.webhookDeliveryQ,
      IncidentRoom: !!c.env.IncidentRoom,
      RateLimiter: !!c.env.RateLimiter,
      TaskTimer: !!c.env.TaskTimer,
      ShelterCounter: !!c.env.ShelterCounter,
      AmbulanceQueue: !!c.env.AmbulanceQueue,
      AgencyRoom: !!c.env.AgencyRoom,
      cache: !!c.env.cache,
      locales: !!c.env.locales,
      embeddings: !!c.env.embeddings,
      metrics: !!c.env.metrics,
      ai: !!c.env.ai,
    },
    environment: c.env.ENVIRONMENT,
  });
});

